// Independent path test: prefix vertices form a path; binary search their diameter.
#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<int>at(n);for(int i=0,v;i<n;++i){cin>>v;at[v]=i;}vector<vector<int>>g(n);for(int i=1,u,v;i<n;++i){cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}int K=1;while((1<<K)<=n)++K;vector<vector<int>>up(K,vector<int>(n));vector<int>depth(n),order{0};for(size_t i=0;i<order.size();++i){int u=order[i];for(int v:g[u])if(v!=up[0][u]){up[0][v]=u;depth[v]=depth[u]+1;order.push_back(v);}}for(int j=1;j<K;++j)for(int v=0;v<n;++v)up[j][v]=up[j-1][up[j-1][v]];
auto lca=[&](int x,int y){if(depth[x]<depth[y])swap(x,y);int diff=depth[x]-depth[y];for(int j=0;j<K;++j)if(diff>>j&1)x=up[j][x];if(x==y)return x;for(int j=K-1;j>=0;--j)if(up[j][x]!=up[j][y]){x=up[j][x];y=up[j][y];}return up[0][x];};auto dist=[&](int x,int y){return depth[x]+depth[y]-2*depth[lca(x,y)];};auto on=[&](int v,int x,int y){return dist(x,v)+dist(v,y)==dist(x,y);};vector<pair<int,int>>prefix{{0,0},{at[0],at[0]}};int l=at[0],r=l;for(int value=1;value<n;++value){int v=at[value];if(on(v,l,r)){}else if(on(r,l,v))r=v;else if(on(l,r,v))l=v;else break;prefix.emplace_back(l,r);}int cap=prefix.size()-1;
while(q--){int x,y;cin>>x>>y;--x;--y;int lo=0,hi=cap+1;while(lo+1<hi){int mid=(lo+hi)/2;auto [a,b]=prefix[mid];if(on(a,x,y)&&on(b,x,y))lo=mid;else hi=mid;}cout<<lo<<'\n';}}
